	// inbound only and is stored in the keyring; it is never echoed back.
	AddAccount(context.Context, *connect.Request[v1.AddAccountRequest]) (*connect.Response[v1.AddAccountResponse], error)
	// RefreshAccount replaces the stored credential blob for an existing account.
	// The credential travels inbound only and is stored in the keyring; it is never echoed back.
	RefreshAccount(context.Context, *connect.Request[v1.RefreshAccountRequest]) (*connect.Response[v1.RefreshAccountResponse], error)
	// UpdateAccount mutates account metadata. Mutable fields are optional
	// (present-only update semantics).
	UpdateAccount(context.Context, *connect.Request[v1.UpdateAccountRequest]) (*connect.Response[v1.UpdateAccountResponse], error)
	// RemoveAccount deletes the account row and purges its keyring credential.
	RemoveAccount(context.Context, *connect.Request[v1.RemoveAccountRequest]) (*connect.Response[v1.RemoveAccountResponse], error)
	// TestAccount validates the account's stored credential and, when provider
	// verification is available, runs a trivial CLI invocation. It records the
	// outcome (last_test_ok_at / last_test_error) and never tears down a session.
	TestAccount(context.Context, *connect.Request[v1.TestAccountRequest]) (*connect.Response[v1.TestAccountResponse], error)
	// RepairDoctor returns a structured health report for the auto-repair
	// pipeline: which plugins are loaded, whether the workflow is running,
	// whether `claude` is on the daemon's PATH, and a summary of recent
	// repair attempts. Surfaced via `boss repair doctor`.
	RepairDoctor(context.Context, *connect.Request[v1.RepairDoctorRequest]) (*connect.Response[v1.RepairDoctorResponse], error)
	// StartRepairWorkflow (re-)arms the auto-repair workflow: it declares the
	// repair plugin's desired-started state (from current daemon settings) and
	// ensures the workflow is running. No-op when already RUNNING
	// (already_running=true) — a running workflow is never restarted, because
	// StartWorkflow re-entry cancels in-flight repairs. PAUSED is operator
	// intent and is also left untouched (reported in detail). Surfaced via
	// `boss repair start`.
	StartRepairWorkflow(context.Context, *connect.Request[v1.StartRepairWorkflowRequest]) (*connect.Response[v1.StartRepairWorkflowResponse], error)
	// ListCheckSnapshots returns the daemon's per-poll record of what it
	// saw for a session's CI checks plus the DisplayStatus it computed.
	// Surfaced via `boss session checks <id>` so the operator can answer
	// "why does the TUI think this PR is passing when GitHub says
	// failing?" without re-running `gh pr checks` by hand.
	ListCheckSnapshots(context.Context, *connect.Request[v1.ListCheckSnapshotsRequest]) (*connect.Response[v1.ListCheckSnapshotsResponse], error)
	// ListAgents returns the names + GetInfo metadata of every agent runner
	// plugin currently loaded. Used by the boss TUI to (a) decide whether to
	// show the onboarding wizard, (b) populate the new-session agent-select
	// step, (c) render the settings page's per-plugin sections.
	ListAgents(context.Context, *connect.Request[v1.ListAgentsRequest]) (*connect.Response[v1.ListAgentsResponse], error)
	// ListPlugins returns every plugin the daemon attempted to load this
	// run, including disabled and failed entries. Surfaced via
	// `boss plugin list` so operators can debug "did my plugin actually
	// load?" without grepping daemon logs.
	ListPlugins(context.Context, *connect.Request[v1.ListPluginsRequest]) (*connect.Response[v1.ListPluginsResponse], error)
	// GetSettings returns the TUI-editable subset of global settings
	// (settings.json): the top-level worktree/poll/tracing knobs plus each
	// configured agent's enabled flag and dynamic config map.
	GetSettings(context.Context, *connect.Request[v1.GetSettingsRequest]) (*connect.Response[v1.GetSettingsResponse], error)
	// UpdateSettings applies a partial update to global settings. Only the
	// optional scalar fields that are set are applied; per-agent updates upsert
	// config keys (an empty value deletes the key). Validation mirrors the boss
	// TUI settings form and the update is persisted atomically to settings.json.
	UpdateSettings(context.Context, *connect.Request[v1.UpdateSettingsRequest]) (*connect.Response[v1.UpdateSettingsResponse], error)
