// DaemonServiceHandler is an implementation of the bossanova.v1.DaemonService service.
type DaemonServiceHandler interface {
	// Context resolution
	ResolveContext(context.Context, *connect.Request[v1.ResolveContextRequest]) (*connect.Response[v1.ResolveContextResponse], error)
	// Repo management
	ValidateRepoPath(context.Context, *connect.Request[v1.ValidateRepoPathRequest]) (*connect.Response[v1.ValidateRepoPathResponse], error)
	RegisterRepo(context.Context, *connect.Request[v1.RegisterRepoRequest]) (*connect.Response[v1.RegisterRepoResponse], error)
	CloneAndRegisterRepo(context.Context, *connect.Request[v1.CloneAndRegisterRepoRequest]) (*connect.Response[v1.CloneAndRegisterRepoResponse], error)
	ListRepos(context.Context, *connect.Request[v1.ListReposRequest]) (*connect.Response[v1.ListReposResponse], error)
	RemoveRepo(context.Context, *connect.Request[v1.RemoveRepoRequest]) (*connect.Response[v1.RemoveRepoResponse], error)
	UpdateRepo(context.Context, *connect.Request[v1.UpdateRepoRequest]) (*connect.Response[v1.UpdateRepoResponse], error)
	// GetRepoSettings returns the web-safe (secret-masked) settings for a repo.
	GetRepoSettings(context.Context, *connect.Request[v1.GetRepoSettingsRequest]) (*connect.Response[v1.GetRepoSettingsResponse], error)
	ListRepoPRs(context.Context, *connect.Request[v1.ListRepoPRsRequest]) (*connect.Response[v1.ListRepoPRsResponse], error)
	ListTrackerIssues(context.Context, *connect.Request[v1.ListTrackerIssuesRequest]) (*connect.Response[v1.ListTrackerIssuesResponse], error)
	// Session lifecycle
	CreateSession(context.Context, *connect.Request[v1.CreateSessionRequest], *connect.ServerStream[v1.CreateSessionResponse]) error
	GetSession(context.Context, *connect.Request[v1.GetSessionRequest]) (*connect.Response[v1.GetSessionResponse], error)
	ListSessions(context.Context, *connect.Request[v1.ListSessionsRequest]) (*connect.Response[v1.ListSessionsResponse], error)
	AttachSession(context.Context, *connect.Request[v1.AttachSessionRequest], *connect.ServerStream[v1.AttachSessionResponse]) error
	StopSession(context.Context, *connect.Request[v1.StopSessionRequest]) (*connect.Response[v1.StopSessionResponse], error)
	PauseSession(context.Context, *connect.Request[v1.PauseSessionRequest]) (*connect.Response[v1.PauseSessionResponse], error)
	ResumeSession(context.Context, *connect.Request[v1.ResumeSessionRequest]) (*connect.Response[v1.ResumeSessionResponse], error)
	RetrySession(context.Context, *connect.Request[v1.RetrySessionRequest]) (*connect.Response[v1.RetrySessionResponse], error)
	CloseSession(context.Context, *connect.Request[v1.CloseSessionRequest]) (*connect.Response[v1.CloseSessionResponse], error)
	MergeSession(context.Context, *connect.Request[v1.MergeSessionRequest]) (*connect.Response[v1.MergeSessionResponse], error)
	RemoveSession(context.Context, *connect.Request[v1.RemoveSessionRequest]) (*connect.Response[v1.RemoveSessionResponse], error)
	UpdateSession(context.Context, *connect.Request[v1.UpdateSessionRequest]) (*connect.Response[v1.UpdateSessionResponse], error)
	LinkSessionPR(context.Context, *connect.Request[v1.LinkSessionPRRequest]) (*connect.Response[v1.LinkSessionPRResponse], error)
	// RefreshSessionPR fetches one linked PR from the VCS provider immediately,
	// updates the daemon's cached/display PR state, and returns the refreshed
	// session snapshot. It accepts a session id, a PR number, or both.
	RefreshSessionPR(context.Context, *connect.Request[v1.RefreshSessionPRRequest]) (*connect.Response[v1.RefreshSessionPRResponse], error)
	// SwitchSessionAccount stops the session's live chat, rebinds the session to
	// the chosen rotation account, and brings the chat back up under it —
	// resuming the prior conversation cross-account when feasible, else fresh.
	// A mid-turn (WORKING) chat is refused unless force is set (operator confirm).
	SwitchSessionAccount(context.Context, *connect.Request[v1.SwitchSessionAccountRequest]) (*connect.Response[v1.SwitchSessionAccountResponse], error)
	// Archive / resurrect
	ArchiveSession(context.Context, *connect.Request[v1.ArchiveSessionRequest]) (*connect.Response[v1.ArchiveSessionResponse], error)
	// ResurrectSession re-creates the archived session's worktree, runs the
	// repo's setup script in it, and restarts the agent. Server-streaming for
	// the same reason CreateSession is (BOS-984): the setup script alone may run
	// for gitpkg.SetupScriptTimeout (5 minutes), and no unary response can
	// outlast the daemon's own http.Server WriteTimeout (120s) — so a slow setup
	// returned deadline_exceeded against a daemon that was working perfectly.
	//
	// This RPC is bossd-local. The versioned surface bosso serves is
	// OrchestratorService.ProxyResurrectSession, whose request/response shapes
	// are deliberately unchanged by this conversion, so no apiversion bump is
	// owed (lib/bossalib/apiversion is installed only on the orchestrator
	// handler; see the note in server.go's StreamCreateSession).
	ResurrectSession(context.Context, *connect.Request[v1.ResurrectSessionRequest], *connect.ServerStream[v1.ResurrectSessionResponse]) error
	EmptyTrash(context.Context, *connect.Request[v1.EmptyTrashRequest]) (*connect.Response[v1.EmptyTrashResponse], error)
	// Claude chat tracking
	RecordChat(context.Context, *connect.Request[v1.RecordChatRequest]) (*connect.Response[v1.RecordChatResponse], error)
	ListChats(context.Context, *connect.Request[v1.ListChatsRequest]) (*connect.Response[v1.ListChatsResponse], error)
	UpdateChatTitle(context.Context, *connect.Request[v1.UpdateChatTitleRequest]) (*connect.Response[v1.UpdateChatTitleResponse], error)
	DeleteChat(context.Context, *connect.Request[v1.DeleteChatRequest]) (*connect.Response[v1.DeleteChatResponse], error)
	// WakeChat brings a previously-started chat back to life when its tmux
	// session has died (host reboot, manual kill, OOM). Idempotent under
	// concurrent calls via per-chat singleflight. Decides --resume vs
	// --session-id by pre-flight stat of the Claude transcript file.
	WakeChat(context.Context, *connect.Request[v1.WakeChatRequest]) (*connect.Response[v1.WakeChatResponse], error)
	// DescribeChatLaunch returns the exact command bossd uses to launch a chat's
	// agent in its worktree, plus the daemon host. The TUI calls it when a
	// freshly-launched pane dies on startup so it can show a copy-pasteable
	// reproduction command — the usual cause is a PATH / login-shell problem that
	// only reproduces on the daemon host. Read-only: it re-derives argv via the
	// same per-agent BuildInteractiveCommand the spawn path uses.
	DescribeChatLaunch(context.Context, *connect.Request[v1.DescribeChatLaunchRequest]) (*connect.Response[v1.DescribeChatLaunchResponse], error)
	// DescribeChatMCP reports which MCP servers a chat's agent actually resolved,
	// with tool counts, tool-name prefixes, auth status and source, by routing to
	// the owning agent plugin's DescribeMCPSurface under the chat's OWN re-derived
	// environment. Read-only; it starts no coding turn.
	DescribeChatMCP(context.Context, *connect.Request[v1.DescribeChatMCPRequest]) (*connect.Response[v1.DescribeChatMCPResponse], error)
	// GetChatTranscript returns a chat's conversation and final result by routing
	// to the owning agent plugin's ReadTranscript. Request-response (pollable).
	GetChatTranscript(context.Context, *connect.Request[v1.GetChatTranscriptRequest]) (*connect.Response[v1.GetChatTranscriptResponse], error)
	// SendChatMessage delivers a user message into a chat's live agent (waking it
	// first if asleep) by bracketed-paste, then returns. Drives follow-up turns
	// and cross-agent "second opinion" prompts without an interactive attach.
	SendChatMessage(context.Context, *connect.Request[v1.SendChatMessageRequest]) (*connect.Response[v1.SendChatMessageResponse], error)
	// Chat status (cross-client heartbeat sharing)
	ReportChatStatus(context.Context, *connect.Request[v1.ReportChatStatusRequest]) (*connect.Response[v1.ReportChatStatusResponse], error)
	GetChatStatuses(context.Context, *connect.Request[v1.GetChatStatusesRequest]) (*connect.Response[v1.GetChatStatusesResponse], error)
	GetSessionStatuses(context.Context, *connect.Request[v1.GetSessionStatusesRequest]) (*connect.Response[v1.GetSessionStatusesResponse], error)
	// VCS event delivery (orchestrator → daemon via webhook routing)
	DeliverVCSEvent(context.Context, *connect.Request[v1.DeliverVCSEventRequest]) (*connect.Response[v1.DeliverVCSEventResponse], error)
	// Auth change notification (CLI → daemon)
	NotifyAuthChange(context.Context, *connect.Request[v1.NotifyAuthChangeRequest]) (*connect.Response[v1.NotifyAuthChangeResponse], error)
	// GetAuthState reports the RUNNING daemon's live upstream auth state.
	// Surfaced via `boss daemon doctor`. It exists because a locally readable
	// credential record says nothing about whether this daemon can actually
	// talk to the orchestrator: the BOS-942 incident had a present, parseable
	// `workos-tokens-v1` record throughout while re-registration failed every
	// 30s. Only the daemon itself is an authority on that, so a local re-read
	// is architecturally incapable of catching it.
	GetAuthState(context.Context, *connect.Request[v1.GetAuthStateRequest]) (*connect.Response[v1.GetAuthStateResponse], error)
	// CreateCronJob registers a new scheduled prompt for a repo.
	CreateCronJob(context.Context, *connect.Request[v1.CreateCronJobRequest]) (*connect.Response[v1.CreateCronJobResponse], error)
	// ListCronJobs returns cron jobs, optionally filtered by repo.
	ListCronJobs(context.Context, *connect.Request[v1.ListCronJobsRequest]) (*connect.Response[v1.ListCronJobsResponse], error)
	// GetCronJob returns a single cron job by id.
	GetCronJob(context.Context, *connect.Request[v1.GetCronJobRequest]) (*connect.Response[v1.GetCronJobResponse], error)
	// UpdateCronJob mutates an existing cron job. Mutable fields are optional.
	UpdateCronJob(context.Context, *connect.Request[v1.UpdateCronJobRequest]) (*connect.Response[v1.UpdateCronJobResponse], error)
	// DeleteCronJob removes a cron job. Sessions previously spawned by it
	// have their cron_job_id reset to NULL (no cascade).
	DeleteCronJob(context.Context, *connect.Request[v1.DeleteCronJobRequest]) (*connect.Response[v1.DeleteCronJobResponse], error)
	// RunCronJobNow fires a cron job immediately, ignoring its schedule.
	// Subject to the same overlap and concurrency-cap rules as scheduled fires.
	RunCronJobNow(context.Context, *connect.Request[v1.RunCronJobNowRequest]) (*connect.Response[v1.RunCronJobNowResponse], error)
	// CreateGithubCallback registers a durable one-shot PR-event callback. The
	// server applies defaults (24h expiry, active state, lowercased repo) and
	// validates the request; lease/trigger/deliver primitives are not exposed.
	CreateGithubCallback(context.Context, *connect.Request[v1.CreateGithubCallbackRequest]) (*connect.Response[v1.CreateGithubCallbackResponse], error)
	// ListGithubCallbacks returns callbacks matching the optional filters,
	// ordered by creation time then id for a deterministic listing.
	ListGithubCallbacks(context.Context, *connect.Request[v1.ListGithubCallbacksRequest]) (*connect.Response[v1.ListGithubCallbacksResponse], error)
	// DeleteGithubCallback removes a callback by id. Idempotent: deleting an
	// absent id succeeds.
	DeleteGithubCallback(context.Context, *connect.Request[v1.DeleteGithubCallbackRequest]) (*connect.Response[v1.DeleteGithubCallbackResponse], error)
	// SendBroadcast resolves a selector to an audience and records one delivery
	// per target; the worker then delivers them asynchronously with retry.
	//
	// Resolution happens ONCE, at send time, and the resolved audience is FROZEN
	// into the delivery rows. A broadcast is a message to the chats that existed
	// and matched when it was sent — never a standing subscription. A chat
	// created (or renamed, or moved to a matching repo) after the send is NOT
	// retroactively included, even while the broadcast is still un-expired and
	// deliveries are still being retried.
	//
	// Two boundary cases callers must not conflate:
	//   - Over the cap: if the selector resolves to more chats than the server's
	//     fan-out cap (MaxTargets), the RPC FAILS, naming the resolved count and
	//     the cap. It never silently truncates to the cap — a partially delivered
	//     broadcast the caller believes was complete is worse than a hard error.
	//   - Zero targets: a selector that resolves to nobody is SUCCESS with zero
	//     deliveries, not an error. "No chat currently matches" is a legitimate
	//     answer, and a coordinator broadcasting to an audience that has already
	//     finished should not have to special-case a failure.
	SendBroadcast(context.Context, *connect.Request[v1.SendBroadcastRequest]) (*connect.Response[v1.SendBroadcastResponse], error)
	// ListBroadcasts returns broadcasts matching the optional filters, ordered by
	// creation time then id for a deterministic listing.
	ListBroadcasts(context.Context, *connect.Request[v1.ListBroadcastsRequest]) (*connect.Response[v1.ListBroadcastsResponse], error)
	// DeleteBroadcast removes a broadcast and its deliveries by id. Idempotent:
	// deleting an absent id succeeds.
	DeleteBroadcast(context.Context, *connect.Request[v1.DeleteBroadcastRequest]) (*connect.Response[v1.DeleteBroadcastResponse], error)
	// CreateNote records a note. The server validates it (repo id required,
	// non-empty body within the size cap) and normalises tags — trimmed,
	// lowercased, de-duplicated — before storing them.
	CreateNote(context.Context, *connect.Request[v1.CreateNoteRequest]) (*connect.Response[v1.CreateNoteResponse], error)
	// GetNote returns a single note by id, including its tags.
	GetNote(context.Context, *connect.Request[v1.GetNoteRequest]) (*connect.Response[v1.GetNoteResponse], error)
	// ListNotes returns notes matching the optional filters, ordered by creation
	// time then id for a deterministic listing. The tag filter is ANY-OF (a note
	// matching one listed tag is returned), not all-of.
	ListNotes(context.Context, *connect.Request[v1.ListNotesRequest]) (*connect.Response[v1.ListNotesResponse], error)
	// UpdateNote mutates a note's body and/or tags. Both are optional; an unset
	// field is left alone. A SET tags field REPLACES the note's entire tag set
	// rather than merging into it — sending an empty tag list clears every tag.
	UpdateNote(context.Context, *connect.Request[v1.UpdateNoteRequest]) (*connect.Response[v1.UpdateNoteResponse], error)
	// DeleteNote removes a note and its tags by id. Idempotent: deleting an
	// absent id succeeds.
	DeleteNote(context.Context, *connect.Request[v1.DeleteNoteRequest]) (*connect.Response[v1.DeleteNoteResponse], error)
	// CreateBroadcastSubscription registers a STANDING rule: when the owning
	// session reaches an outcome matching trigger_event, the daemon broadcasts
	// the registered message to the audience the selector resolves — resolved at
	// FIRE time, not now. It is a notification primitive, not an orchestration
	// one: it delivers a message, it does not schedule work.
	//
	// A subscription fires at most once (the store's compare-and-swap on the
	// active state is the guard) and is retired by its expiry if the session
	// never settles.
	//
	// CASCADES ARE NOT DETECTED. The broadcast a subscription fires wakes chats,
	// and those chats may themselves hold subscriptions, so subscriptions can
	// chain. There is NO cycle detection in v1: the fan-out cap (a selector
	// resolving to more chats than the cap is refused outright) and subscription
	// expiry are what bound the blast radius. A caller building a topology where
	// A's completion messages B and B's completion messages A owns that loop.
	CreateBroadcastSubscription(context.Context, *connect.Request[v1.CreateBroadcastSubscriptionRequest]) (*connect.Response[v1.CreateBroadcastSubscriptionResponse], error)
	// ListBroadcastSubscriptions returns subscriptions matching the optional
	// filters, ordered by creation time then id for a deterministic listing. It
	// never returns the registered message body.
	ListBroadcastSubscriptions(context.Context, *connect.Request[v1.ListBroadcastSubscriptionsRequest]) (*connect.Response[v1.ListBroadcastSubscriptionsResponse], error)
	// DeleteBroadcastSubscription retires a standing subscription by id.
	// Idempotent: deleting an absent id, or one that has already fired, been
	// canceled or expired, succeeds.
	DeleteBroadcastSubscription(context.Context, *connect.Request[v1.DeleteBroadcastSubscriptionRequest]) (*connect.Response[v1.DeleteBroadcastSubscriptionResponse], error)
	// ListAccounts returns registry accounts, optionally filtered by provider.
	// Metadata only — credential blobs never cross the wire.
	ListAccounts(context.Context, *connect.Request[v1.ListAccountsRequest]) (*connect.Response[v1.ListAccountsResponse], error)
	// AddAccount registers a new provider login. The credential blob travels
	// inbound only and is stored in the keyring; it is never echoed back.
	AddAccount(context.Context, *connect.Request[v1.AddAccountRequest]) (*connect.Response[v1.AddAccountResponse], error)
	// RefreshAccount replaces the stored credential blob for an existing account.
	// The credential travels inbound only and is stored in the keyring; it is never echoed back.
	RefreshAccount(context.Context, *connect.Request[v1.RefreshAccountRequest]) (*connect.Response[v1.RefreshAccountResponse], error)
	// UpdateAccount mutates account metadata. Mutable fields are optional
	// (present-only update semantics).
	UpdateAccount(context.Context, *connect.Request[v1.UpdateAccountRequest]) (*connect.Response[v1.UpdateAccountResponse], error)
	// RemoveAccount deletes the account row and purges its keyring credential.
	RemoveAccount(context.Context, *connect.Request[v1.RemoveAccountRequest]) (*connect.Response[v1.RemoveAccountResponse], error)
	// TestAccount validates the account's stored credential and, when provider
	// verification is available, runs a trivial CLI invocation. It records the
	// outcome (last_test_ok_at / last_test_error) and never tears down a session.
	TestAccount(context.Context, *connect.Request[v1.TestAccountRequest]) (*connect.Response[v1.TestAccountResponse], error)
	// RepairDoctor returns a structured health report for the auto-repair
	// pipeline: which plugins are loaded, whether the workflow is running,
	// whether `claude` is on the daemon's PATH, and a summary of recent
	// repair attempts. Surfaced via `boss repair doctor`.
	RepairDoctor(context.Context, *connect.Request[v1.RepairDoctorRequest]) (*connect.Response[v1.RepairDoctorResponse], error)
	// StartRepairWorkflow (re-)arms the auto-repair workflow: it declares the
	// repair plugin's desired-started state (from current daemon settings) and
	// ensures the workflow is running. No-op when already RUNNING
	// (already_running=true) — a running workflow is never restarted, because
	// StartWorkflow re-entry cancels in-flight repairs. PAUSED is operator
	// intent and is also left untouched (reported in detail). Surfaced via
	// `boss repair start`.
	StartRepairWorkflow(context.Context, *connect.Request[v1.StartRepairWorkflowRequest]) (*connect.Response[v1.StartRepairWorkflowResponse], error)
	// ListCheckSnapshots returns the daemon's per-poll record of what it
	// saw for a session's CI checks plus the DisplayStatus it computed.
	// Surfaced via `boss session checks <id>` so the operator can answer
	// "why does the TUI think this PR is passing when GitHub says
	// failing?" without re-running `gh pr checks` by hand.
	ListCheckSnapshots(context.Context, *connect.Request[v1.ListCheckSnapshotsRequest]) (*connect.Response[v1.ListCheckSnapshotsResponse], error)
	// ListAgents returns the names + GetInfo metadata of every agent runner
	// plugin currently loaded. Used by the boss TUI to (a) decide whether to
	// show the onboarding wizard, (b) populate the new-session agent-select
	// step, (c) render the settings page's per-plugin sections.
	ListAgents(context.Context, *connect.Request[v1.ListAgentsRequest]) (*connect.Response[v1.ListAgentsResponse], error)
	// ListPlugins returns every plugin the daemon attempted to load this
	// run, including disabled and failed entries. Surfaced via
	// `boss plugin list` so operators can debug "did my plugin actually
	// load?" without grepping daemon logs.
	ListPlugins(context.Context, *connect.Request[v1.ListPluginsRequest]) (*connect.Response[v1.ListPluginsResponse], error)
	// GetSettings returns the TUI-editable subset of global settings
	// (settings.json): the top-level worktree/poll/tracing knobs plus each
	// configured agent's enabled flag and dynamic config map.
	GetSettings(context.Context, *connect.Request[v1.GetSettingsRequest]) (*connect.Response[v1.GetSettingsResponse], error)
	// UpdateSettings applies a partial update to global settings. Only the
	// optional scalar fields that are set are applied; per-agent updates upsert
	// config keys (an empty value deletes the key). Validation mirrors the boss
	// TUI settings form and the update is persisted atomically to settings.json.
	UpdateSettings(context.Context, *connect.Request[v1.UpdateSettingsRequest]) (*connect.Response[v1.UpdateSettingsResponse], error)
}

